//! Rule R across a reconfiguration, with the real binary: three producing
//! validators, one of them restarted with an acknowledged change.
//!
//! Each validator is the real `sumchain` binary on its own data directory, a
//! NONPRODUCTION three-validator devnet (chain id 1337, keys generated by the
//! binary itself), every listener on a kernel-assigned loopback port, and each
//! node's libp2p identity persisted in its data directory as a deployed node's
//! is. The test follows the operator's procedure for a non-gate change:
//!
//! 1. the three run one chain and verify each other;
//! 2. one is stopped; its genesis's `min_fee` is moved; its start refuses and
//!    names `acknowledge-consensus-config --old … --new …`; the command is run,
//!    and the node started again. Its handshake digest differs, so it and the
//!    other two refuse each other: it is partitioned from them;
//! 3. it is stopped, its genesis restored, the change acknowledged back, and it
//!    is started again. A validator that compared and refused its changed
//!    declaration still holds it `Incompatible`, banned, for the life of that
//!    process, so it does not admit the restored node;
//! 4. once the holders restart, all three verify each other and blocks flow.
//!
//! Which side of a refused pair compares the other's declaration first is a
//! race: the first to compare bans and disconnects, and the other's request
//! may then fail and leave it holding nothing. A validator that holds nothing
//! admits the restored node at once, which is the same rule (the refusal lasts
//! as long as the process that holds it). The changed node is restarted until
//! at least one of the other two holds the refusal, so that the holder's case
//! is always exercised.
#![cfg(unix)]

use std::fs;
use std::io::Read;
use std::path::{Path, PathBuf};
use std::process::{Child, Command, Stdio};
use std::time::{Duration, Instant};

const BIN: &str = env!("CARGO_BIN_EXE_sumchain");

/// Long enough for three nodes to bind, mesh (each waits for its mesh before
/// producing) and produce a few blocks at the devnet's block time.
const LONG: Duration = Duration::from_secs(120);
/// Long enough for a refused pair to show it would have been admitted.
const QUIET: Duration = Duration::from_secs(8);

struct Validator {
    name: &'static str,
    home: PathBuf,
    key: PathBuf,
    child: Option<Child>,
    log: PathBuf,
    starts: usize,
    peer_id: String,
    addr: String,
}

impl Validator {
    fn new(root: &Path, name: &'static str) -> (Self, String) {
        let home = root.join(name);
        fs::create_dir_all(&home).unwrap();
        let key = home.join("validator.json");
        let out = Command::new(BIN)
            .args(["keygen", "--output"])
            .arg(&key)
            .output()
            .unwrap();
        assert!(out.status.success(), "keygen failed: {out:?}");
        let pk = String::from_utf8_lossy(&out.stdout)
            .lines()
            .find_map(|l| l.strip_prefix("Public key: ").map(str::to_owned))
            .expect("keygen prints the public key");
        let v = Validator {
            name,
            log: home.join("log-0.txt"),
            home,
            key,
            child: None,
            starts: 0,
            peer_id: String::new(),
            addr: String::new(),
        };
        (v, pk)
    }

    fn data(&self) -> PathBuf {
        self.home.join("data")
    }

    fn config(&self, genesis: &Path, bootnodes: &[String]) -> PathBuf {
        let path = self.home.join("node.toml");
        let boot = bootnodes
            .iter()
            .map(|b| format!("\"{b}\""))
            .collect::<Vec<_>>()
            .join(", ");
        fs::write(
            &path,
            format!(
                r#"[node]
genesis = "{g}"
data_dir = "{d}"
validator_key = "{k}"
[consensus]
engine = "poa"
[network]
listen_addr = "/ip4/127.0.0.1/tcp/0"
bootnodes = [{boot}]
mdns = false
[rpc]
addr = "127.0.0.1:0"
[health]
addr = "127.0.0.1:0"
[logging]
level = "info"
json = false
"#,
                g = genesis.display(),
                d = self.data().display(),
                k = self.key.display(),
            ),
        )
        .unwrap();
        path
    }

    fn next_log(&mut self) -> fs::File {
        self.starts += 1;
        self.log = self.home.join(format!("log-{}.txt", self.starts));
        fs::File::create(&self.log).unwrap()
    }

    fn spawn(&mut self, genesis: &Path, bootnodes: &[String]) -> Child {
        let config = self.config(genesis, bootnodes);
        let f = self.next_log();
        Command::new(BIN)
            .args(["run", "--config"])
            .arg(config)
            .env("NO_COLOR", "1")
            .stdout(Stdio::from(f.try_clone().unwrap()))
            .stderr(Stdio::from(f))
            .spawn()
            .unwrap()
    }

    /// Start, and wait until it listens; its peer id must be the one it had.
    fn start(&mut self, genesis: &Path, bootnodes: &[String]) {
        assert!(self.child.is_none(), "{} is already running", self.name);
        self.child = Some(self.spawn(genesis, bootnodes));
        let (mut id, mut addr) = (None, None);
        let found = wait_until(LONG, || {
            let text = self.log_text();
            id = text
                .lines()
                .find_map(|l| l.split("Local peer ID: ").nth(1).map(|s| s.trim().to_owned()));
            addr = text.lines().find_map(|l| {
                l.split("Listening on: ")
                    .nth(1)
                    .filter(|a| a.starts_with("/ip4/127.0.0.1/tcp/"))
                    .map(|a| a.trim().to_owned())
            });
            id.is_some() && addr.is_some()
        });
        assert!(found, "{} never listened; log:\n{}", self.name, self.log_text());
        let id = id.unwrap();
        if !self.peer_id.is_empty() {
            assert_eq!(id, self.peer_id, "{}'s identity persists", self.name);
        }
        self.peer_id = id;
        self.addr = addr.unwrap();
    }

    /// A start that the consensus-configuration check refuses: the commitments
    /// it names for `acknowledge-consensus-config`.
    fn refused_start(&mut self, genesis: &Path, bootnodes: &[String]) -> (String, String) {
        let mut child = self.spawn(genesis, bootnodes);
        let t = Instant::now();
        let status = loop {
            if let Some(st) = child.try_wait().unwrap() {
                break st;
            }
            assert!(
                t.elapsed() < LONG,
                "{}'s start was not refused; log:\n{}",
                self.name,
                self.log_text()
            );
            std::thread::sleep(Duration::from_millis(100));
        };
        assert!(!status.success(), "{} started: {status:?}", self.name);
        let text = self.log_text();
        let rest = text
            .split("acknowledge-consensus-config --old ")
            .nth(1)
            .unwrap_or_else(|| panic!("{} names no acknowledgement; log:\n{text}", self.name));
        let old = rest[..66].to_owned();
        let new = rest[66..]
            .strip_prefix(" --new ")
            .map(|r| r[..66].to_owned())
            .expect("--new follows --old");
        (old, new)
    }

    fn acknowledge(&self, genesis: &Path, old: &str, new: &str) {
        let out = Command::new(BIN)
            .args(["acknowledge-consensus-config", "--data-dir"])
            .arg(self.data())
            .arg("--genesis")
            .arg(genesis)
            .args(["--old", old, "--new", new, "--yes"])
            .env("NO_COLOR", "1")
            .output()
            .unwrap();
        assert!(out.status.success(), "{}: acknowledgement failed: {out:?}", self.name);
    }

    /// SIGINT, and a clean exit: the database lock is released.
    fn stop(&mut self) {
        let mut child = self.child.take().expect("running");
        let st = Command::new("kill")
            .arg("-INT")
            .arg(child.id().to_string())
            .status()
            .unwrap();
        assert!(st.success());
        let t = Instant::now();
        let status = loop {
            if let Some(st) = child.try_wait().unwrap() {
                break st;
            }
            assert!(t.elapsed() < LONG, "{} did not stop", self.name);
            std::thread::sleep(Duration::from_millis(100));
        };
        assert!(status.success(), "{} stopped uncleanly: {status:?}", self.name);
    }

    fn bootnode(&self) -> String {
        format!("{}/p2p/{}", self.addr, self.peer_id)
    }

    fn log_text(&self) -> String {
        let mut s = String::new();
        if let Ok(mut f) = fs::File::open(&self.log) {
            let _ = f.read_to_string(&mut s);
        }
        s
    }

    /// This process's log from byte `mark` on.
    fn since(&self, mark: usize) -> String {
        self.log_text().get(mark..).unwrap_or_default().to_owned()
    }

    fn mark(&self) -> usize {
        self.log_text().len()
    }
}

impl Drop for Validator {
    fn drop(&mut self) {
        if let Some(mut c) = self.child.take() {
            let _ = c.kill();
            let _ = c.wait();
        }
    }
}

fn wait_until(within: Duration, mut done: impl FnMut() -> bool) -> bool {
    let t = Instant::now();
    while t.elapsed() < within {
        if done() {
            return true;
        }
        std::thread::sleep(Duration::from_millis(250));
    }
    done()
}

fn accepted(log: &str, peer: &str) -> bool {
    log.lines()
        .any(|l| l.contains("compatibility handshake accepted") && l.contains(peer))
}

fn refused(log: &str, peer: &str) -> bool {
    log.contains(&format!("REFUSING peer {peer}:"))
}

/// Heights this process produced, in its log from `mark` on.
fn produced(log: &str) -> Vec<u64> {
    log.lines()
        .filter_map(|l| l.split(" at height ").nth(1).filter(|_| l.contains("Produced block")))
        .filter_map(|h| h.trim().parse().ok())
        .collect()
}

fn genesis(path: &Path, validators: &[String], min_fee: u64, time: u128) {
    let list = validators
        .iter()
        .map(|v| format!("\"{v}\""))
        .collect::<Vec<_>>()
        .join(",");
    fs::write(
        path,
        format!(
            r#"{{"chain_id":1337,"genesis_time":{time},"validators":[{list}],"alloc":{{}},
 "params":{{"block_time_ms":500,"max_block_bytes":1000000,"max_txs_per_block":1000,"min_fee":{min_fee}}}}}"#
        ),
    )
    .unwrap();
}

/// Three producing validators. One is restarted with an acknowledged
/// `min_fee` change: it and the other two refuse each other. Restored and
/// restarted, it is still refused by every validator that holds the refusal,
/// until that validator restarts; then all three verify each other and blocks
/// flow again.
#[test]
fn a_validator_restarted_with_an_acknowledged_change_is_partitioned_until_the_holders_restart() {
    let root = tempfile::tempdir().unwrap();
    let (mut a, pa) = Validator::new(root.path(), "a");
    let (mut b, pb) = Validator::new(root.path(), "b");
    let (mut c, pc) = Validator::new(root.path(), "c");
    let time = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap()
        .as_millis();
    let original = root.path().join("genesis.json");
    let changed = root.path().join("genesis-min-fee-moved.json");
    genesis(&original, &[pa.clone(), pb.clone(), pc.clone()], 1, time);
    genesis(&changed, &[pa, pb, pc], 2, time);

    // ── 1. The three run one chain. ─────────────────────────────────────────
    a.start(&original, &[]);
    b.start(&original, &[a.bootnode()]);
    c.start(&original, &[a.bootnode(), b.bootnode()]);
    let one_chain = |a: &Validator, b: &Validator, c: &Validator, marks: [usize; 3], above: u64| {
        let logs = [a.since(marks[0]), b.since(marks[1]), c.since(marks[2])];
        let pairs = [
            (&logs[0], &b.peer_id),
            (&logs[0], &c.peer_id),
            (&logs[1], &a.peer_id),
            (&logs[1], &c.peer_id),
            (&logs[2], &a.peer_id),
            (&logs[2], &b.peer_id),
        ];
        let heights: Vec<Vec<u64>> = logs.iter().map(|l| produced(l)).collect();
        pairs.iter().all(|(log, peer)| accepted(log, peer))
            && heights.iter().all(|h| h.iter().any(|x| *x > above))
            && heights.iter().flatten().any(|x| *x >= above + 6)
    };
    assert!(
        wait_until(LONG, || one_chain(&a, &b, &c, [0, 0, 0], 0)),
        "the three never ran one chain; logs:\n--- a\n{}\n--- b\n{}\n--- c\n{}",
        a.log_text(),
        b.log_text(),
        c.log_text()
    );

    // ── 2. C restarts with an acknowledged min_fee change. ──────────────────
    c.stop();
    let (old, new) = c.refused_start(&changed, &[a.bootnode(), b.bootnode()]);
    assert_ne!(old, new);
    c.acknowledge(&changed, &old, &new);
    let mut holders: Vec<&'static str> = Vec::new();
    for attempt in 1..=3 {
        let marks = [a.mark(), b.mark()];
        c.start(&changed, &[a.bootnode(), b.bootnode()]);
        let apart = |x: &Validator, mark: usize| {
            refused(&x.since(mark), &c.peer_id) || refused(&c.log_text(), &x.peer_id)
        };
        assert!(
            wait_until(LONG, || apart(&a, marks[0]) && apart(&b, marks[1])),
            "attempt {attempt}: C and the others never refused each other; logs:\n--- a\n{}\n--- b\n{}\n--- c\n{}",
            a.since(marks[0]),
            b.since(marks[1]),
            c.log_text()
        );
        std::thread::sleep(QUIET);
        for (x, mark) in [(&a, marks[0]), (&b, marks[1])] {
            assert!(!accepted(&x.since(mark), &c.peer_id), "{} admitted the changed C", x.name);
            assert!(!accepted(&c.log_text(), &x.peer_id), "the changed C admitted {}", x.name);
            if refused(&x.since(mark), &c.peer_id) && !holders.contains(&x.name) {
                holders.push(x.name);
            }
        }
        // C is partitioned: it imports nothing from them; at its own turns it
        // can only extend its own copy.
        if !holders.is_empty() {
            break;
        }
        c.stop();
    }
    assert!(
        !holders.is_empty(),
        "in three attempts neither A nor B compared C's declaration first"
    );
    eprintln!("validators holding the changed C's refusal: {holders:?}");

    // ── 3. C restored and restarted: refused by every holder. ───────────────
    c.stop();
    let (old, new) = c.refused_start(&original, &[a.bootnode(), b.bootnode()]);
    c.acknowledge(&original, &old, &new);
    let marks = [a.mark(), b.mark()];
    c.start(&original, &[a.bootnode(), b.bootnode()]);
    std::thread::sleep(QUIET);
    for (x, mark) in [(&a, marks[0]), (&b, marks[1])] {
        if holders.contains(&x.name) {
            std::thread::sleep(QUIET);
            assert!(
                !accepted(&x.since(mark), &c.peer_id),
                "{} holds C's refusal and must not admit the restored C; its log:\n{}",
                x.name,
                x.since(mark)
            );
            assert!(
                !accepted(&c.log_text(), &x.peer_id),
                "the restored C must not be admitted by {}, which holds its refusal",
                x.name
            );
        } else {
            // Only C held this pair's refusal, and C restarted.
            assert!(
                wait_until(LONG, || accepted(&x.since(mark), &c.peer_id)
                    && accepted(&c.log_text(), &x.peer_id)),
                "{} held nothing and must admit the restored C",
                x.name
            );
        }
    }
    let before = [a.log_text(), b.log_text(), c.log_text()]
        .iter()
        .flat_map(|l| produced(l))
        .max()
        .unwrap_or(0);

    // ── 4. The holders restart: one chain again. ────────────────────────────
    let c_mark = c.mark();
    a.stop();
    b.stop();
    a.start(&original, &[c.bootnode()]);
    b.start(&original, &[a.bootnode(), c.bootnode()]);
    assert!(
        wait_until(LONG, || one_chain(&a, &b, &c, [0, 0, c_mark], before)),
        "after the holders restarted the three never ran one chain again (from height {before}); \
         logs:\n--- a\n{}\n--- b\n{}\n--- c\n{}",
        a.log_text(),
        b.log_text(),
        c.since(c_mark)
    );
}
